import{_ as t,c as o,o as a,a3 as e}from"./chunks/framework.C5U8cnJv.js";const l="/xhh-blog/assets/image-12.Cy8_6tvv.png",s="/xhh-blog/assets/image-11.7ubJJn-Q.png",k=JSON.parse('{"title":"Github Copilot","description":"","frontmatter":{},"headers":[],"relativePath":"ai/githubcopilot.md","filePath":"ai/githubcopilot.md"}'),i={name:"ai/githubcopilot.md"},n=e(`<h1 id="github-copilot" tabindex="-1">Github Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;Github Copilot&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>GitHub Copilot 是 GitHub（微软旗下）推出的编程辅助工具；产品早期与 OpenAI 合作，最初基于 OpenAI Codex 模型。现在 Copilot 是多模型平台，支持 GPT、Claude、Gemini 等多家厂商大模型，在编辑器内提供自动补全、代码片段建议、整段实现和注释生成等能力。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>以 VS Code 为例</p><ol><li>打开 VS Code。</li><li>在扩展市场（Extensions）中搜索 “GitHub Copilot”，或直接搜索 <code>Copilot</code> 并选择由 GitHub 发布的插件安装。</li><li>安装完成后，你需要使用 GitHub 账号登录并完成授权（安装后通常会弹出登录引导窗口，按提示完成）。</li></ol><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><p>1.Ctrl+Alt+I‌ (Control+Command+I) 打开聊天界面；</p><p>2.选中行 =&gt; Add Selection to Chat;</p><p>3.在输入代码或注释时，Copilot 会以灰色 &quot;ghost text&quot; 形式给出建议，按 Tab 接受建议，按 ‌Esc‌ 忽略；</p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><blockquote><p>官方文档：<a href="https://docs.github.com/zh/copilot/reference/ai-models/supported-models" target="_blank" rel="noreferrer">https://docs.github.com/zh/copilot/reference/ai-models/supported-models</a></p></blockquote><p>GitHub Copilot 是多模型平台，接入 OpenAI GPT、Anthropic Claude、Google Gemini 等多家厂商的代码大模型。 模型分为两类：<strong>可手动选择对话模型</strong>（Agent/聊天面板下拉切换，Auto模式可自动择优）、<strong>后台Utility模型</strong>（专供行内幽灵代码补全，无法手动选择）。</p><p>额度规则：灰色行内代码补全不限量，不消耗AI Credits；Agent对话、MCP工具调用会消耗月度AI Credits。免费版仅支持Auto自动调度，Pro订阅可手动切换模型；不同订阅套餐开放的模型范围不同。</p><blockquote><p>⚠️ 说明：Copilot是GitHub后端代理调用模型，不等同直接使用OpenAI原生API，模型使用权仅限Copilot IDE内。</p></blockquote><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>项目级：</p><ul><li>.github/skills/</li><li>.agents/skills/</li><li>.claude/skills/</li></ul><p>个人全局skills(所有项目生效)</p><ul><li>~/.copilot/skills/</li><li>~/.agents/skills/</li><li>~/.claude/skills/</li></ul><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>Skills</th><th>Plugins（Agent Plugin）</th></tr></thead><tbody><tr><td>层级定位</td><td>最小<strong>能力单元</strong>，是给Agent阅读的任务规则文档</td><td>打包<strong>分发包/容器</strong>，用于批量分发整套Agent自定义资源</td></tr><tr><td>包含内容</td><td>仅任务指令 <code>SKILL.md</code>（单个子文件夹内）</td><td>可包含 Skills、MCP Servers、Agents、Hooks、Prompts、Commands</td></tr><tr><td>加载来源</td><td>自动扫描固定目录：<br>✅ 项目：<code>.github/skills</code> / <code>.agents/skills</code> / <code>.claude/skills</code><br>✅ 全局用户目录：<code>~/.copilot/skills</code> / <code>~/.agents/skills</code> / <code>~/.claude/skills</code><br>✅ 已安装Plugin内部自带技能</td><td>通过Plugins面板 <code>Install</code> 导入（本地路径/远程URL），导入后内部资源自动注册</td></tr><tr><td>面板归类</td><td>加载后在 <code>Skills</code> 面板展示，分 Workspace / User 分组</td><td>在 <code>Plugins</code> 面板管理；打包内的Skills会自动出现在Skills列表</td></tr><tr><td>加载触发</td><td>Agent根据任务上下文，<strong>按需自动加载匹配的skill</strong></td><td>插件一旦安装，包内所有资源一次性注册就绪，Agent可直接调用</td></tr><tr><td>主要用途</td><td>项目本地编写、维护独立小能力，跟随代码仓库提交共享</td><td>团队/社区打包一整套Agent方案分发</td></tr><tr><td>鉴权相关</td><td>Skill本身不携带凭证</td><td>Plugin仅定义MCP服务配置，<strong>不会携带个人账号token</strong>，首次调用MCP仍需手动授权</td></tr><tr><td>生效前提</td><td>仅Agent模式(Copilot/Local载体)生效，普通聊天/代码补全无效</td><td>安装完成后，内部所有资源同样仅Agent模式可用</td></tr></tbody></table><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>连接 Figma MCP</p><h3 id="第一种-项目工作区配置" tabindex="-1">第一种：项目工作区配置 <a class="header-anchor" href="#第一种-项目工作区配置" aria-label="Permalink to &quot;第一种：项目工作区配置&quot;">​</a></h3><p>项目根目录 .vscode 文件夹下 新建 mcp.json:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;inputs&quot;: [],</span></span>
<span class="line"><span>  &quot;servers&quot;: {</span></span>
<span class="line"><span>    &quot;figma&quot;: {</span></span>
<span class="line"><span>      &quot;type&quot;: &quot;http&quot;,</span></span>
<span class="line"><span>      &quot;url&quot;: &quot;https://mcp.figma.com/mcp&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存后，在 mcp.json 文件中点击 figma 上方的 Start，连接 Figma MCP</p><h3 id="第二种-copilot-设置里配置" tabindex="-1">第二种：Copilot 设置里配置 <a class="header-anchor" href="#第二种-copilot-设置里配置" aria-label="Permalink to &quot;第二种：Copilot 设置里配置&quot;">​</a></h3><p>Copilot 设置里找到 MCP Servers，安装 Figma MCP Server <img src="`+l+'" alt="alt text"></p><p>启动服务</p><p><img src="'+s+'" alt="alt text"></p><p>同意授权即可。</p><h3 id="第三种-用户全局配置-本机所有项目生效" tabindex="-1">第三种：用户全局配置（本机所有项目生效） <a class="header-anchor" href="#第三种-用户全局配置-本机所有项目生效" aria-label="Permalink to &quot;第三种：用户全局配置（本机所有项目生效）&quot;">​</a></h3><p>1.打开命令面板，执行 <code>MCP: Add Server</code></p><p>2.选择<code>http</code>类型，填入 Figma MCP 地址 <code>https://mcp.figma.com/mcp</code></p><p>3.选择保存为<strong>User 设置（全局）</strong>，启动并完成授权。</p><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档&quot;">​</a></h2><p><a href="https://docs.github.com/zh/copilot" target="_blank" rel="noreferrer">https://docs.github.com/zh/copilot</a></p>',39),d=[n];function p(r,c,h,u,g,b){return a(),o("div",null,d)}const q=t(i,[["render",p]]);export{k as __pageData,q as default};
